package com.llmcouncil.mobile.data
import android.content.*
import android.database.sqlite.*
import com.llmcouncil.mobile.model.*
class ModelHealthDb(context:Context):SQLiteOpenHelper(context,"llm_council_health.db",null,2){
 override fun onCreate(db:SQLiteDatabase){db.execSQL("CREATE TABLE model_health(model_key TEXT PRIMARY KEY,source TEXT NOT NULL,successes INTEGER NOT NULL DEFAULT 0,failures INTEGER NOT NULL DEFAULT 0,consecutive_failures INTEGER NOT NULL DEFAULT 0,last_status TEXT NOT NULL DEFAULT 'untested',last_error TEXT,last_tested_at INTEGER NOT NULL DEFAULT 0,last_success_at INTEGER NOT NULL DEFAULT 0,qualification_version INTEGER NOT NULL DEFAULT 0,qualification_passed INTEGER NOT NULL DEFAULT 0,last_qualified_at INTEGER NOT NULL DEFAULT 0)")}
 override fun onUpgrade(db:SQLiteDatabase,o:Int,n:Int){if(o<2){db.execSQL("ALTER TABLE model_health ADD COLUMN qualification_version INTEGER NOT NULL DEFAULT 0");db.execSQL("ALTER TABLE model_health ADD COLUMN qualification_passed INTEGER NOT NULL DEFAULT 0");db.execSQL("ALTER TABLE model_health ADD COLUMN last_qualified_at INTEGER NOT NULL DEFAULT 0")}}
 fun record(k:String,success:Boolean,error:String?=null){write(k,success,error,false,0)};fun recordQualification(k:String,v:Int,passed:Boolean,error:String?=null){write(k,passed,error,true,v)}
 private fun write(k:String,ok:Boolean,error:String?,qualification:Boolean,v:Int){val now=System.currentTimeMillis();val old=get(k);val cv=base(k,old).apply{put("successes",(old?.successes?:0)+if(ok)1 else 0);put("failures",(old?.failures?:0)+if(ok)0 else 1);put("consecutive_failures",if(ok)0 else (old?.consecutiveFailures?:0)+1);put("last_status",if(ok)"working" else "failed");put("last_error",if(ok)null else error?.take(800));put("last_tested_at",now);put("last_success_at",if(ok)now else(old?.lastSuccessAt?:0L));if(qualification){put("qualification_version",v);put("qualification_passed",if(ok)1 else 0);put("last_qualified_at",now)}};writableDatabase.insertWithOnConflict("model_health",null,cv,SQLiteDatabase.CONFLICT_REPLACE)}
 private fun base(k:String,o:ModelHealth?)=ContentValues().apply{put("model_key",k);put("source",ModelSource.fromKey(k).name);put("successes",o?.successes?:0);put("failures",o?.failures?:0);put("consecutive_failures",o?.consecutiveFailures?:0);put("last_status",o?.lastStatus?:"untested");put("last_error",o?.lastError);put("last_tested_at",o?.lastTestedAt?:0L);put("last_success_at",o?.lastSuccessAt?:0L);put("qualification_version",o?.qualificationVersion?:0);put("qualification_passed",if(o?.qualificationPassed==true)1 else 0);put("last_qualified_at",o?.lastQualifiedAt?:0L)}
 fun get(k:String):ModelHealth?{readableDatabase.query("model_health",null,"model_key=?",arrayOf(k),null,null,null).use{c->if(!c.moveToFirst())return null;return c.health()}};fun list():List<ModelHealth>{readableDatabase.query("model_health",null,null,null,null,null,"last_tested_at DESC").use{c->val r=mutableListOf<ModelHealth>();while(c.moveToNext())r+=c.health();return r}};fun clear(){writableDatabase.delete("model_health",null,null)}
 private fun android.database.Cursor.health()=ModelHealth(getString(getColumnIndexOrThrow("model_key")),runCatching{ModelSource.valueOf(getString(getColumnIndexOrThrow("source")))}.getOrDefault(ModelSource.OPENROUTER),getInt(getColumnIndexOrThrow("successes")),getInt(getColumnIndexOrThrow("failures")),getInt(getColumnIndexOrThrow("consecutive_failures")),getString(getColumnIndexOrThrow("last_status")),getString(getColumnIndexOrThrow("last_error")),getLong(getColumnIndexOrThrow("last_tested_at")),getLong(getColumnIndexOrThrow("last_success_at")),getInt(getColumnIndexOrThrow("qualification_version")),getInt(getColumnIndexOrThrow("qualification_passed"))!=0,getLong(getColumnIndexOrThrow("last_qualified_at")))
}
